<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Data\ExtensionManifest; use Azuriom\Plugin\GamingHubCore\Exceptions\InvalidExtensionManifest;
final class ExtensionManifestValidator { private const TYPES=['integration','game-integration','feature','theme-companion','utility']; public function validate(array $m,array $plugin):ExtensionManifest { if(($m['schema']??null)!==1)throw new InvalidExtensionManifest('Unsupported extension manifest schema.');$id=$this->id($m['id']??null);if($id==='gaming-hub-core')throw new InvalidExtensionManifest('Gaming Hub Core is protected from self-installation.');if(($plugin['id']??null)!==$id)throw new InvalidExtensionManifest('Manifest and plugin identifier mismatch.');$ver=(string)($m['version']??'');if(($plugin['version']??null)!==$ver)throw new InvalidExtensionManifest('Manifest and plugin version mismatch.');if(!preg_match('/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/',$ver))throw new InvalidExtensionManifest('Invalid extension version.');$type=(string)($m['type']??'');if(!in_array($type,self::TYPES,true)||$type==='theme-companion') { if(!in_array($type,self::TYPES,true))throw new InvalidExtensionManifest('Unsupported extension type.'); } if($type==='theme-companion')throw new InvalidExtensionManifest('Theme installation is not supported in v0.6.0.');$req=$m['requires']??[];foreach(['gaming-hub-core','azuriom','php'] as $key)if(!is_string($req[$key]??null)||trim($req[$key])==='')throw new InvalidExtensionManifest('Missing '.$key.' constraint.');$pkg=$m['package']??[];$dir=$this->id($pkg['plugin_directory']??null);if($dir!==$id)throw new InvalidExtensionManifest('plugin_directory must match extension ID.');$alg=strtolower((string)($pkg['checksum_algorithm']??'sha256'));if($alg!=='sha256')throw new InvalidExtensionManifest('Only SHA-256 is supported.');$provides=$this->declarations($m['provides']??[]);$consumes=$this->declarations($m['consumes']??[]);return new ExtensionManifest(1,$id,$this->text($m['name']??'',150),$ver,$type,$this->text($m['description']??'',1000),$this->text($m['author']??'',150),isset($m['homepage'])?(string)$m['homepage']:null,isset($m['repository'])?(string)$m['repository']:null,$req,$provides,$consumes,$dir,$alg,isset($m['public_attribution_label'])?$this->text($m['public_attribution_label'],150):null,$m); }
 private function id(mixed $v):string{$v=(string)$v;if(!preg_match('/^[a-z0-9][a-z0-9-]{1,98}[a-z0-9]$/',$v))throw new InvalidExtensionManifest('Invalid identifier.');return $v;} private function text(mixed $v,int $max):string{$v=trim((string)$v);if(mb_strlen($v)>$max||preg_match('/<[^>]+>/',$v))throw new InvalidExtensionManifest('Invalid text field.');return $v;}
 private function declarations(mixed $v):array {if(!is_array($v))throw new InvalidExtensionManifest('Invalid declarations.');foreach($v as $group=>$items){if(!is_array($items))throw new InvalidExtensionManifest('Invalid declaration group.');if(count($items)!==count(array_unique($items)))throw new InvalidExtensionManifest('Duplicate declaration.');foreach($items as $item)if(!is_string($item)||!preg_match('/^[a-z0-9][a-z0-9._-]{1,127}$/',$item))throw new InvalidExtensionManifest('Invalid declaration value.');}return $v;}
}
